   "wording":{"default":"התוכנית השפיעה עליי ושינתה את הדרך שבה אני חושב/ת על התחום","a_c":"התוכנית לימדה אותי משהו שאזכור"}},
  {"key":"s_post_open_like","metric":"satisfaction","type":"free_text","audiences":["student"],"stages":["post"],"sort":910,"required":false,
