   "wording":{"default":"אם היית מעביר/ה את התוכנית שוב, מה היית עושה אחרת?"}}
]$json$::jsonb) as q(
  key text, program text, metric text, type text, audiences text[], stages text[], comparison boolean,
  sort int, required boolean, wording jsonb, options jsonb, scoring jsonb
)
on conflict (question_key) do nothing;

-- Course-specific questions, audited against each catalog page (summary, goals, skills, closing products).
-- Student questionnaires stay short: per program 2–3 comparison questions (asked in PRE and POST)
-- + 1–2 POST-only questions, i.e. at most 5 course questions in any student questionnaire.
-- The catalog source of each question is noted in "src".
insert into public.feedback_questions (
  question_key, program_key, metric_key, question_type, audiences, stages, is_comparison,
  sort_order, default_required, wording, options, scoring
)
select q.key, q.program, q.metric, 'rating_1_5', q.audiences, q.stages, coalesce(q.comparison, false),
  q.sort, true, q.wording, '[]'::jsonb, '{"include_in_score": true}'::jsonb
from jsonb_to_recordset($json$[
  {"key":"biomimicry_example","program":"biomimicry","metric":"knowledge","audiences":["student"],"stages":["pre","post"],"comparison":true,"sort":100,
   "src":"6089/53828: היכרות עם דוגמאות ביומימטיות והמצאות בהשראת הטבע",
