-- Templates: program x (student pre, student post, educational staff, instructor).
insert into public.feedback_templates (program_key, audience, stage, title)
select p.key, s.audience, s.stage, p.title || ' – ' || s.label
from public.feedback_programs p
cross join (values
  ('student', 'pre', 'תלמידים – פתיחה'),
  ('student', 'post', 'תלמידים – סיום'),
  ('educational_staff', 'final', 'צוות חינוכי'),
  ('instructor', 'final', 'מדריך')
) as s(audience, stage, label)
on conflict (program_key, audience, stage) do nothing;

-- v1 for every template that has no version yet: compose (core + course) and publish.
do $$
declare
  t record;
  v_version uuid;
begin
  for t in
    select tp.* from public.feedback_templates tp
    where not exists (select 1 from public.feedback_template_versions v where v.template_id = tp.id)
  loop
    v_version := private.feedback_compose_draft(t.id);
    update public.feedback_template_versions
    set intro_text = case
      when t.audience = 'student' and t.stage = 'pre' then 'לפני שמתחילים – נשמח לדעת מה אתם חושבים ומרגישים. אין תשובות נכונות או לא נכונות, והשאלון אנונימי.'
      when t.audience = 'student' then 'סיימנו את התוכנית! נשמח לשמוע איך היה ומה השתנה אצלכם. השאלון אנונימי.'
      when t.audience = 'educational_staff' then 'נשמח לשמוע את הערכתכם לגבי התוכנית ולגבי מה שראיתם אצל התלמידים. המשוב עוזר לנו להשתפר.'
      else 'חשוב לנו לשמוע מה את/ה באמת חושב/ת על התוכן, על הקבוצה ועל התפעול. המשוב מגיע לצוות הניהול של תעשיידע בלבד.'
    end,
    notes = 'גרסת ברירת מחדל'
    where id = v_version;
    perform private.feedback_publish_version(v_version);
  end loop;
end $$;

notify pgrst, 'reload schema';
